## Переключение тем Переключение тем

```jsx
import React, { useLayoutEffect, useState } from 'react';
import { Switch } from '@salutejs/sdds-finai/css';

const App = () => {
    const [theme, setTheme] = useState('light');

    useLayoutEffect(() => {
        document.documentElement.className = theme;
    }, [theme]);

    return (
        <div className="wrapper">
            <Switch
                label={`app theme: ${theme}`}
                onChange={() => {
                    setTheme((theme) => (theme === 'light' ? 'dark' : 'light'));
                }}
            />
        </div>
    );
};

export default App;
```

В файле, где происходит подключение всех стилей, например  `index.css` ```css
@import '@salutejs/sdds-themes/css/sdds_finai.module.css';
```

```jsx
import React, { useLayoutEffect, useState } from 'react';

import { Switch } from '@salutejs/sdds-finai/css';
import webThemes from '@salutejs/sdds-themes/css/sdds_finai.module.css';

const App = () => {
    const [theme, setTheme] = useState('light');

    useLayoutEffect(() => {
        document.documentElement.className = webThemes[theme];
    }, [theme]);

    return (
        <div className="wrapper">
            <Switch
                label={`app theme: ${theme}`}
                onChange={() => {
                    setTheme((theme) => (theme === 'light' ? 'dark' : 'light'));
                }}
            />
        </div>
    );
};

export default App;
```

```jsx
import React, { useState } from 'react';
import { createGlobalStyle } from 'styled-components';

import { Switch } from '@salutejs/sdds-finai';
import { sdds_finai__light, sdds_finai__dark } from '@salutejs/sdds-themes';

const LightTheme = createGlobalStyle(sdds_finai__light);
const DarkTheme = createGlobalStyle(sdds_finai__dark);

const App = () => {
    const [theme, setTheme] = useState('light');

    return (
        <>
            {theme === 'light' ? <LightTheme /> : <DarkTheme />}

            <div className="wrapper">
                <Switch
                    label={`app theme: ${theme}`}
                    onChange={() => {
                        setTheme((theme) => (theme === 'light' ? 'dark' : 'light'));
                    }}
                />
            </div>
        </>
    );
};

export default App;
```

```jsx
import React, { useState } from 'react';
import { Global, css } from '@emotion/react';

import { Switch } from '@salutejs/sdds-finai/emotion';
import { sdds_finai__light, sdds_finai__dark } from '@salutejs/sdds-themes';

const lightThemeStyle = css(sdds_finai__light);
const darkThemeStyle = css(sdds_finai__dark);

const App = () => {
    const [theme, setTheme] = useState('light');

    return (
        <>
            <Global styles={theme === 'light' ? lightThemeStyle : darkThemeStyle} />

            <div className="wrapper">
                <Switch
                    label={`app theme: ${theme}`}
                    onChange={() => setTheme((theme) => (theme === 'light' ? 'dark' : 'light'))}
                />
            </div>
        </>
    );
};

export default App;
```

## Подключение темы Подключение темы Тема включает в себя цветовые и типографические токены и подключается один раз в корне приложения. :::info
Точкой входа является корень приложения: Если вы используете  Create React App , делайте вызов внутри  `src/index.tsx` . Если вы используете  Next.js , создайте файл  `pages/_app.tsx`  и подключите стили в нем.
::: Доступны светлая и тёмная темы —  `sdds_finai__light`  и  `sdds_finai__dark` .

```jsx
import React from 'react';
import { Button, BodyL } from '@salutejs/sdds-finai/css';

import '@salutejs/sdds-themes/css/sdds_finai__light.css';

const App = () => {
    return (
        <>
            <BodyL>Hello world</BodyL>
            <Button text="This is themed button" />
        </>
    );
};

export default App;
```

Или подключите тему в файле, где собраны все стили приложения, например  `index.css` ```css
@import '@salutejs/sdds-themes/css/sdds_finai__light.css';
```

```jsx
import React from 'react';
import { Button, BodyL } from '@salutejs/sdds-finai/css';

import styles from '@salutejs/sdds-themes/css/sdds_finai.module.css';

const App = () => {
    return (
        <div className={styles.light}>
            <BodyL>Hello world</BodyL>
            <Button text="This is themed button" />
        </div>
    );
};

export default App;
```

```jsx
import React from 'react';
import { createGlobalStyle } from 'styled-components';
import { Button, BodyL } from '@salutejs/sdds-finai';
import { sdds_finai__light } from '@salutejs/sdds-themes';

const Theme = createGlobalStyle(sdds_finai__light);

const App = () => {
    return (
        <>
            <Theme />
            <BodyL>Hello world</BodyL>
            <Button text="This is themed button" />
        </>
    );
};

export default App;
```

```jsx
import React from 'react';
import { Global, css } from '@emotion/react';
import { Button, BodyL } from '@salutejs/sdds-finai/emotion';
import { sdds_finai__light } from '@salutejs/sdds-themes';

const themeStyle = css(sdds_finai__light);

const App = () => {
    return (
        <>
            <Global styles={themeStyle} />
            <BodyL>Hello world</BodyL>
            <Button text="This is themed button" />
        </>
    );
};

export default App;
```

